const head=`#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\nAdafruit_SSD1306 display(128, 64, &Wire, -1);\n\nvoid setup() {\n  Wire.begin(5, 4); // SDA = 5, SCL = 4\n  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);\n}\n`;
export const examples={eyes:head+`\nvoid loop() {\n  display.clearDisplay();\n  // 改改圆心的位置和半径\n  display.fillCircle(40, 32, 14, SSD1306_WHITE);\n  display.fillCircle(88, 32, 14, SSD1306_WHITE);\n  display.display();\n  delay(1500);\n\n  // 闭上眼睛\n  display.clearDisplay();\n  display.fillRect(26, 30, 28, 4, SSD1306_WHITE);\n  display.fillRect(74, 30, 28, 4, SSD1306_WHITE);\n  display.display();\n  delay(180);\n}\n`,move:head+`\nvoid loop() {\n  for (int x = 30; x <= 50; x++) {\n    display.clearDisplay();\n    display.drawCircle(40, 32, 18, SSD1306_WHITE);\n    display.drawCircle(88, 32, 18, SSD1306_WHITE);\n    display.fillCircle(x, 32, 6, SSD1306_WHITE);\n    display.fillCircle(x + 48, 32, 6, SSD1306_WHITE);\n    display.display();\n    delay(45);\n  }\n  delay(400);\n}\n`,text:head+`\nvoid loop() {\n  display.clearDisplay();\n  display.setTextColor(SSD1306_WHITE);\n  display.setTextSize(2);\n  display.setCursor(10, 22);\n  display.print("Hello!");\n  display.display();\n  delay(1000);\n}\n`,led:`// 板载灯不需要外接杜邦线\nvoid setup() {\n  pinMode(8, OUTPUT);\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  digitalWrite(8, LOW);\n  Serial.println("LED ON");\n  delay(500);\n  digitalWrite(8, HIGH);\n  Serial.println("LED OFF");\n  delay(500);\n}\n`};
